import json,tempfile,threading
from pathlib import Path
from types import SimpleNamespace
import omega_prime.agent.rlm as module
from omega_prime.session.persist import load_session
observed={}
with tempfile.TemporaryDirectory(prefix="rlm-delete-order-") as d:
    root=Path(d)
    finish=threading.Event(); terminal_entered=threading.Event(); release_terminal=threading.Event()
    def runner(prompt,model=None,thinking=None):
        if not finish.wait(5): raise RuntimeError("runner barrier expired")
        return "private-terminal-answer"
    host=module.RlmHost(SimpleNamespace(session_dir=root,session_name="owner",max_children=4,max_depth=2,depth=0),run_child=runner)
    original=host._persist_child
    def delayed(child,*,status,directory=None):
        if status=="completed":
            terminal_entered.set()
            if not release_terminal.wait(5): raise RuntimeError("terminal barrier expired")
        return original(child,status=status,directory=directory)
    host._persist_child=delayed
    handle=host.spawn("child-only",name="child")
    record=host._children[handle.rlm_child_id]
    finish.set()
    assert terminal_entered.wait(5)
    deletion=host.delete_subagent(handle)
    status_at_delete=load_session(root,record.session_id)["metadata"]["status"]
    release_terminal.set(); assert record.settled_on_disk.wait(5)
    status_after_callback=load_session(root,record.session_id)["metadata"]["status"]
    fresh=module.RlmHost(SimpleNamespace(session_dir=root,session_name="owner",max_children=4,max_depth=2,depth=0))
    observed["delete_settle_race"]={"deletion":deletion,"status_when_delete_returned":status_at_delete,"status_after_delayed_terminal_callback":status_after_callback,"fresh_host_children":len(fresh.list_subagents())}
    host.shutdown();fresh.shutdown()
with tempfile.TemporaryDirectory(prefix="rlm-delete-save-failure-") as d:
    root=Path(d); finish=threading.Event()
    def runner(prompt,model=None,thinking=None):
        if not finish.wait(5): raise RuntimeError("runner barrier expired")
        return "answer"
    host=module.RlmHost(SimpleNamespace(session_dir=root,session_name="owner",max_children=4,max_depth=2,depth=0),run_child=runner)
    handle=host.spawn("child-only",name="child")
    record=host._children[handle.rlm_child_id]
    original_save=module.save_session
    def broken(root,session_id,messages,metadata):
        if metadata["status"]=="deleted": raise OSError("injected atomic tombstone failure")
        return original_save(root,session_id,messages,metadata)
    module.save_session=broken
    try:
        try: host.delete_subagent(handle)
        except OSError as exc: observed["delete_save_failure"]={"error":str(exc),"visible_children_after_failed_delete":len(host.list_subagents()),"persisted_status":load_session(root,record.session_id)["metadata"]["status"]}
    finally:
        module.save_session=original_save; finish.set(); assert record.settled_on_disk.wait(5);host.shutdown()
print(json.dumps(observed,sort_keys=True))
assert observed["delete_settle_race"]["status_after_delayed_terminal_callback"]=="completed"
assert observed["delete_settle_race"]["fresh_host_children"]==1
assert observed["delete_save_failure"]["visible_children_after_failed_delete"]==0

